  const row=ATECO_NODE_INDEX.get(code);if(!row)return null;
  return {code:row[0],officialDescription:row[1],hierarchyLevel:row[2],parent:row[3]||null,terminal:row[4]===1,selectable:row[4]===1,order:row[5],classificationRelease:AtecoClassificationRelease.id,sourceId:AtecoClassificationRelease.sourceId};
