  const limit=input.limit===undefined?20:input.limit;
  const rules=['ATECO_2025_OFFICIAL_CATALOG_SEARCH','ATECO_SEARCH_NO_FUZZY_NORMALIZATION'];
  if(query.length<2)return result(null,STATUS.BLOCKED,null,[diag('ATECO_SEARCH_QUERY_TOO_SHORT','query','Inserire almeno due caratteri del codice o della descrizione ufficiale.')],rules);
  if(!Number.isInteger(limit)||limit<1||limit>50)return result(null,STATUS.BLOCKED,null,[diag('ATECO_SEARCH_LIMIT_INVALID','limit','Il limite dei risultati deve essere un intero tra 1 e 50.')],rules);
  const normalized=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it-IT');
  const matches=ATECO_CATALOG_PACKED.filter(row=>row[4]===1).map(row=>{
    const code=String(row[0]),description=String(row[1]),haystack=description.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it-IT');
    let rank=9;if(code===query)rank=0;else if(code.startsWith(query))rank=1;else if(haystack.startsWith(normalized))rank=2;else if(haystack.includes(normalized))rank=3;else return null;
    return {rank,order:row[5],node:getAtecoNode(code)};
  }).filter(Boolean).sort((a,b)=>a.rank-b.rank||a.order-b.order);
  return result(null,STATUS.CALCULATED,{query,totalMatches:matches.length,items:matches.slice(0,limit).map(item=>item.node)},[],rules);
