function stateCollections(state){return state&&state.schemaVersion===LEDGER_SCHEMA_VERSION&&Array.isArray(state.activities)&&Array.isArray(state.invoices)&&Array.isArray(state.creditNotes)&&Array.isArray(state.payments)&&Array.isArray(state.allocations)&&Array.isArray(state.refunds);}
