function testCreditFlow(verified){
  let state=testSimplePaid('2025-02-01','2025-03-01',100000);state=ledgerMust(recordCreditNote(state,{type:'credit_note',id:'N1',originalInvoiceId:'I1',issueDate:'2026-01-15',currency:'EUR',components:[{id:'NC1',originalComponentId:'C1',amountCents:20000}]}),'credit');
  const treatment=verified?{status:'verified',threshold:'REDUCE',forfaitIncome:'REDUCE',vatTurnover:'NONE',pensionSubjectiveBase:'REDUCE',pensionIntegrativeBase:'NONE',evidenceId:'E-REF1',reason:'Restituzione documentata della quota reddituale stornata.'}:{status:'to_reconcile'};
  const out=recordRefund(state,{type:'refund',id:'R1',invoiceId:'I1',cashDate:'2026-02-10',currency:'EUR',amountCents:20000,activityId:'A78',taxTreatment:treatment});return {before:state,out,state:out.value&&(out.value.state||out.value)};
}
function testOrderState(reverse){
  let state=ledgerMust(createLedgerState({activities:[{id:'A40',coefficientBps:4000},{id:'A78',coefficientBps:7800}]}));
  const docs=[{type:'invoice',id:'OI1',issueDate:'2025-01-02',currency:'EUR',components:[testComponent('compensation','OC1','OI1',40000,'A40')]},{type:'invoice',id:'OI2',issueDate:'2025-01-03',currency:'EUR',components:[testComponent('compensation','OC2','OI2',78000,'A78')]}];
  for(const doc of reverse?[...docs].reverse():docs)state=ledgerMust(recordDocument(state,doc));
  const payments=[{id:'OP1',invoiceId:'OI1',cashDate:'2025-02-01',currency:'EUR',amountCents:40000,cashReceivedCents:40000,withholdingCents:0,componentId:'OC1',allocationId:'OA1'},{id:'OP2',invoiceId:'OI2',cashDate:'2025-02-02',currency:'EUR',amountCents:78000,cashReceivedCents:78000,withholdingCents:0,componentId:'OC2',allocationId:'OA2'}];
  for(const item of reverse?[...payments].reverse():payments){state=ledgerMust(recordPayment(state,{id:item.id,invoiceId:item.invoiceId,cashDate:item.cashDate,currency:'EUR',amountCents:item.amountCents,cashReceivedCents:item.cashReceivedCents,withholdingCents:0}));state=ledgerMust(allocatePayment(state,{id:item.allocationId,paymentId:item.id,componentId:item.componentId,amountCents:item.amountCents}));}
  return state;
}
function explicitPlanForAmount(state,invoiceId,paymentId,amountCents,prefix){
  let left=amountCents,index=0;const plan=[],balance=balanceInternal(state,invoiceId);for(const component of balance.effectiveComponents){const available=component.residualCents,take=Math.min(left,available);if(take>0){plan.push({id:`${prefix}${++index}`,paymentId,componentId:component.componentId,amountCents:take});left-=take;}if(left===0)break;}if(left!==0)throw new Error('Fixture allocation capacity mismatch');return plan;
}
function buildComplexLedgerFixture(){
  let state=ledgerMust(createLedgerState({activities:[{id:'A40',coefficientBps:4000},{id:'A78',coefficientBps:7800}]}));
  for(let i=1;i<=30;i++){
    const n=String(i).padStart(2,'0'),invoiceId=`FI${n}`,activityId=i%2?'A40':'A78',issueYear=i<=15?2025:2026,day=String(((i-1)%20)+1).padStart(2,'0'),components=[testComponent('compensation',`FC${n}-1`,invoiceId,10000+i*137,activityId)];
    if(i%3===0)components.push(testComponent('gs_recourse',`FC${n}-2`,invoiceId,400+i,activityId));if(i%4===0)components.push(testComponent('cassa_integrative',`FC${n}-3`,invoiceId,500+i,activityId));if(i%5===0)components.push(testComponent('stamp',`FC${n}-4`,invoiceId,200,activityId));if(i%6===0)components.push(testComponent('art15',`FC${n}-5`,invoiceId,700));
    state=ledgerMust(recordDocument(state,{type:'invoice',id:invoiceId,issueDate:`${issueYear}-01-${day}`,currency:'EUR',components}),`complex invoice ${i}`);
    if(i===5||i===10)state=ledgerMust(recordCreditNote(state,{type:'credit_note',id:`FN${n}`,originalInvoiceId:invoiceId,issueDate:'2025-02-20',currency:'EUR',components:[{id:`FNC${n}`,originalComponentId:`FC${n}-1`,amountCents:500}]}),`complex credit ${i}`);
    const total=balanceInternal(state,invoiceId).adjustedDocumentCents,first=Math.floor(total/2),second=total-first,firstYear=issueYear,secondYear=issueYear===2025?2026:2026;
    const p1={id:`FP${n}-1`,invoiceId,cashDate:`${firstYear}-06-${day}`,currency:'EUR',amountCents:first,cashReceivedCents:first,withholdingCents:0};state=ledgerMust(recordPayment(state,p1));for(const allocation of explicitPlanForAmount(state,invoiceId,p1.id,first,`FA${n}-1-`))state=ledgerMust(allocatePayment(state,allocation));
    const p2={id:`FP${n}-2`,invoiceId,cashDate:`${secondYear}-11-${day}`,currency:'EUR',amountCents:second,cashReceivedCents:second,withholdingCents:0};state=ledgerMust(recordPayment(state,p2));if(i!==30)for(const allocation of explicitPlanForAmount(state,invoiceId,p2.id,second,`FA${n}-2-`))state=ledgerMust(allocatePayment(state,allocation));
  }
  return state;
}
function runLedgerPropertyAudit(iterations){
  let seed=20260909,passed=0;const next=()=>{seed=(seed*1664525+1013904223)>>>0;return seed;};
  for(let i=0;i<iterations;i++){
    const first=1+(next()%500000),second=1+(next()%500000),total=first+second,paymentAmount=1+(next()%total),id=`Q${i}`;
    let state=testStateWithInvoice({id:`I${id}`,issueDate:'2025-01-01',components:[testComponent('compensation',`C${id}-1`,`I${id}`,first,'A40'),testComponent('stamp',`C${id}-2`,`I${id}`,second,'A40')]});
    const payment={id:`P${id}`,invoiceId:`I${id}`,cashDate:'2025-02-01',currency:'EUR',amountCents:paymentAmount,cashReceivedCents:paymentAmount,withholdingCents:0};state=ledgerMust(recordPayment(state,payment));const plan=explicitPlanForAmount(state,`I${id}`,payment.id,paymentAmount,`A${id}-`);for(const allocation of plan)state=ledgerMust(allocatePayment(state,allocation));
    const balance=ledgerMust(calculateDocumentBalance({state,invoiceId:`I${id}`}));
    if(allocatedToPayment(state,payment.id)!==paymentAmount)throw new Error(`property allocation sum ${i}`);if(plan.some(a=>a.amountCents<=0))throw new Error(`property allocation sign ${i}`);if(balance.adjustedDocumentCents!==balance.settledCents+balance.settlementResidualCents)throw new Error(`property balance ${i}`);if(ledgerSum(balance.effectiveComponents.map(c=>c.allocatedCents))!==paymentAmount)throw new Error(`property cents ${i}`);if(JSON.stringify(JSON.parse(JSON.stringify(state)))!==JSON.stringify(state))throw new Error(`property serialization ${i}`);passed++;
  }
  return {iterations,passed,allocationSumExact:true,noResidualOverrun:true,balanceCoherent:true,noCentsCreatedOrLost:true,serializationRoundTrip:true};
}

